<script setup>
import { onMounted, ref } from 'vue'
import { getApiError } from '../../api/client'
import { guardians } from '../../api/students'

const rows=ref([]), loading=ref(true), saving=ref(false), error=ref(''), notice=ref(''), search=ref(''), show=ref(false)
const form=ref({first_name:'',last_name:'',phone:'',alternative_phone:'',email:'',address:'',occupation:'',employer:'',preferred_contact_method:'phone',status:'active'})
const fullName=g=>[g.first_name,g.last_name].filter(Boolean).join(' ')
async function load(){loading.value=true;error.value='';try{rows.value=await guardians.list({search:search.value||undefined})}catch(e){error.value=getApiError(e)}finally{loading.value=false}}
function open(){form.value={first_name:'',last_name:'',phone:'',alternative_phone:'',email:'',address:'',occupation:'',employer:'',preferred_contact_method:'phone',status:'active'};show.value=true}
async function save(){saving.value=true;error.value='';try{await guardians.create(form.value);show.value=false;await load();notice.value='Guardian created successfully.';setTimeout(()=>notice.value='',3000)}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="students-page"><div class="page-title-row"><div><div class="eyebrow">FAMILY & CONTACTS</div><h1>Guardians</h1><p>Manage parents and guardians who are connected to students.</p></div><button class="btn btn-primary" @click="open"><i class="bi bi-person-plus me-2"></i>Add guardian</button></div><div v-if="notice" class="alert alert-success border-0 shadow-sm">{{notice}}</div><div v-if="error" class="alert alert-danger border-0 shadow-sm">{{error}}</div><section class="dashboard-card"><div class="student-toolbar"><div class="search-box"><i class="bi bi-search"></i><input v-model="search" @keyup.enter="load" placeholder="Search name, phone or email..." /></div><button class="btn btn-light" @click="load"><i class="bi bi-arrow-clockwise"></i></button></div><div v-if="loading" class="py-5 text-center"><span class="spinner-border text-primary"></span></div><div v-else-if="!rows.length" class="empty-state"><i class="bi bi-people"></i><h3>No guardians yet</h3><p>Add a guardian, then link them to one or more students.</p><button class="btn btn-primary" @click="open">Add first guardian</button></div><div v-else class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Guardian</th><th>Phone</th><th>Email</th><th>Preferred contact</th><th>Status</th></tr></thead><tbody><tr v-for="g in rows" :key="g.id"><td class="fw-semibold">{{fullName(g)}}</td><td>{{g.phone||'—'}}</td><td>{{g.email||'—'}}</td><td class="text-capitalize">{{g.preferred_contact_method}}</td><td><span class="status-pill" :class="g.status">{{g.status}}</span></td></tr></tbody></table></div></section><div v-if="show" class="modal-backdrop-custom"><div class="modal-card modal-wide"><div class="modal-head"><div><h2>Add guardian</h2><p>Create a family contact that can later be linked to students.</p></div><button class="btn btn-light" @click="show=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-md-6"><label>First name *</label><input v-model="form.first_name" class="form-control" /></div><div class="col-md-6"><label>Last name *</label><input v-model="form.last_name" class="form-control" /></div><div class="col-md-6"><label>Phone</label><input v-model="form.phone" class="form-control" /></div><div class="col-md-6"><label>Alternative phone</label><input v-model="form.alternative_phone" class="form-control" /></div><div class="col-md-6"><label>Email</label><input v-model="form.email" type="email" class="form-control" /></div><div class="col-md-6"><label>Preferred contact</label><select v-model="form.preferred_contact_method" class="form-select"><option value="phone">Phone</option><option value="sms">SMS</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="any">Any</option></select></div><div class="col-md-6"><label>Occupation</label><input v-model="form.occupation" class="form-control" /></div><div class="col-md-6"><label>Employer</label><input v-model="form.employer" class="form-control" /></div><div class="col-12"><label>Address</label><input v-model="form.address" class="form-control" /></div></div><div class="modal-actions"><button class="btn btn-light" @click="show=false">Cancel</button><button class="btn btn-primary" :disabled="saving || !form.first_name || !form.last_name" @click="save">{{saving?'Saving...':'Create guardian'}}</button></div></div></div></div></template>
